def combine_date_time_to_minutes(year, month, day, time_str):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    h, m = time_str.split(':')
    return (doy-1)*1440 + int(h)*60 + int(m)

def common_prefix_counts(words, prefix_len):
    d = {}
    for w in words:
        if len(w) >= prefix_len:
            p = w[:prefix_len]
            d[p] = d.get(p, 0) + 1
    return d

def wrap_greedy(text, width):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= width:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines

def mask_phone_custom_char(digits, ch):
    if len(digits) <= 4:
        return digits
    return ch * (len(digits) - 4) + digits[-4:]

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d):
        take = min(9, remaining)
        digits[i] = take
        remaining -= take
    return int(''.join(map(str, digits)))

def count_semiprimes_in_range(a, b):
    def is_semiprime(x):
        count = 0
        n = x
        p = 2
        while p * p <= n:
            while n % p == 0:
                n //= p
                count += 1
                if count > 2:
                    return False
            p += 1
        if n > 1:
            count += 1
        return count == 2
    return sum(1 for x in range(a, b + 1) if is_semiprime(x))

def is_valid_percentage_string(s):
    if not s.endswith('%') or len(s) < 2:
        return False
    num_part = s[:-1]
    if not all(c.isdigit() or c == '.' for c in num_part):
        return False
    if num_part.count('.') > 1:
        return False
    if num_part.startswith('.') or num_part.endswith('.'):
        return False
    value = float(num_part)
    return 0 <= value <= 100

def collapse_underscores(name):
    out = []
    prev_underscore = False
    for c in name:
        if c == "_":
            if not prev_underscore:
                out.append(c)
            prev_underscore = True
        else:
            out.append(c)
            prev_underscore = False
    return "".join(out).strip("_")

def is_kebab_case(s):
    if not s or s[0] == '-' or s[-1] == '-' or '--' in s:
        return False
    for part in s.split('-'):
        if not part:
            return False
        for c in part:
            if not (c.isdigit() or (c.isalpha() and c.islower())):
                return False
    return True

def reverse_every_k_chars(s, k):
    result = []
    for i in range(0, len(s), k):
        result.append(s[i:i + k][::-1])
    return "".join(result)

def format_id_with_check_digit(n, width):
    padded = str(n).zfill(width)
    check = sum(int(d) for d in padded if d.isdigit()) % 10
    return padded + str(check)

def word_length_distribution(text):
    d = {}
    for w in text.split():
        d[len(w)] = d.get(len(w), 0) + 1
    return d

def is_valid_scientific_notation(s):
    import re
    return re.fullmatch(r'[+-]?\d+(\.\d+)?[eE][+-]?\d+', s) is not None

def intersperse(lst, sep):
    if len(lst) < 2:
        return list(lst)
    out = [lst[0]]
    for x in lst[1:]:
        out.append(sep)
        out.append(x)
    return out

def format_signed_number(n):
    if n > 0:
        return f"+{n}"
    if n < 0:
        return str(n)
    return "0"

def next_power_of_two(n):
    p = 1
    while p < n:
        p *= 2
    return p

def count_character_pairs(s, pair):
    if len(s) < 2:
        return 0
    return sum(1 for i in range(len(s) - 1) if s[i:i + 2] == pair)

def duplicated_items(items):
    c = {}
    for x in items:
        c[x] = c.get(x, 0) + 1
    return sorted(x for x, cnt in c.items() if cnt > 1)

def is_valid_mac_address(s):
    groups = s.split(':')
    if len(groups) != 6:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(len(g) == 2 and all(c in hexdigits for c in g) for g in groups)

def gcd_two(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def sum_of_letter_positions_per_word(s):
    result = []
    for word in s.split():
        total = sum(ord(c.lower()) - ord('a') + 1 for c in word if c.isalpha())
        result.append(total)
    return result

def count_perfect_squares_up_to(n):
    import math
    if n < 1:
        return 0
    return math.isqrt(n)

def plateau_count(lst):
    n = len(lst)
    count = 0
    i = 0
    while i < n:
        j = i
        while j + 1 < n and lst[j + 1] == lst[i]:
            j += 1
        if j - i + 1 >= 2:
            count += 1
        i = j + 1
    return count

def quarter_of_date(year, month, day):
    q = (month - 1)//3 + 1
    return (q, (q-1)*3 + 1)

def shared_key_sum(dicts_list):
    sums = {}
    counts = {}
    for d in dicts_list:
        for k, v in d.items():
            sums[k] = sums.get(k, 0) + v
            counts[k] = counts.get(k, 0) + 1
    return {k: sums[k] for k in sums if counts[k] >= 2}
